To confirm this reasoning through Python code, we can write a function that verifies there are no prime numbers in the interval $(n!+1, n!+n)$ for a given $n$. Let's do this for several values of $n$.
```python
import math

# Function to check if a number is prime
def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

# Function to check the interval (n! + 1, n! + n)
def check_interval(n):
    factorial = math.factorial(n)
    count_primes = 0
    for i in range(1, n):
        number = factorial + i
        if is_prime(number):
            count_primes += 1
    return count_primes

# Check for several values of n
results = {n: check_interval(n) for n in range(2, 11)}
print(results)
```
